async function authorizeUserRequest(req, res, userId) {
  if (!isUserAuthRequired()) return true;
  const auth = await authenticateRequest(req);
  if (!auth) {
    sendJSON(res, 401, { ok: false, error: "session_required" });
    return false;
  }
  if (auth.user.userId !== userId) {
    sendJSON(res, 403, { ok: false, error: "session_user_mismatch" });
    return false;
  }
  return true;
}

async function authenticateRequest(req) {
  const token = readBearerToken(req);
  return await userStore.authenticateSession(token);
}

function readBearerToken(req) {
  const auth = String(req.headers.authorization || "");
  return auth.toLowerCase().startsWith("bearer ") ? auth.slice("Bearer ".length).trim() : "";
}

function isUserAuthRequired() {
  return String(process.env.USER_AUTH_REQUIRED || "true").toLowerCase() !== "false";
}

function dataStoreMode() {
  return String(process.env.DATA_STORE || "memory").toLowerCase();
}

function isGenerationAuthRequired() {
  return String(process.env.GENERATION_AUTH_REQUIRED || "false").toLowerCase() === "true";
}

